"""Generate provenance inventory and copy reviewable documentation into the static site."""
from common import *
import shutil

def main():
    inventory=[]
    for p in sorted(RAW.rglob('*.metadata.json')):
        if '/audit/' in p.as_posix() or '/validation/' in p.as_posix(): continue
        d=json.loads(p.read_text());d['file']=str(p.relative_to(RAW)).replace('.metadata.json','')
        if 'bytes' not in d: d['bytes']=(RAW/d['file']).stat().st_size
        # Full requests stay in raw metadata; publish their hashes and selected years, not repeated 5984-code lists.
        if d.get('request'):
            d['request_sha256']=hashlib.sha256(json.dumps(d.pop('request'),sort_keys=True).encode()).hexdigest()
        inventory.append(d)
    lines=['# Fuentes, descargas y transformaciones','', f'Inventario generado {datetime.now(timezone.utc).isoformat()}. Cada original se conserva sin cambios en `data/raw/` con archivo contiguo de metadatos. La reproducción usa la caché y comprueba SHA-256 antes de reutilizarla. El listado siguiente refleja las descargas reales, no fechas supuestas.', '', '## Transformaciones','', '- Edición 2026: scripts/build_2026.py descarga JSON preliminar firmado, límites 2026, correspondencias oficiales y SCB 2025 sobre DeSO 2025. Ver data_quality_report_2026.md; no son resultados definitivos. Las URLs 2026 están fijadas en ese script.', '- Historia distrital: scripts/build_district_2002.py, build_early_district_history.py, build_district_history.py, build_annual_district_birth.py y build_district_archive.py incorporan todas las elecciones 2002–2026 y observaciones de nacimiento anuales 2010–2025, con coberturas y cortes explícitos. 2002 se valida contra totales nacionales; SD se extrae del desglose de otros. Los cortes territoriales y las estimaciones excluidas por cobertura espacial se conservan. Ver history/districts_2018_provenance.json.', '- Evolución: scripts/build_history.py publica series oficiales 2002–2026 de votos y 2002–2025 de población para Suecia y 290 municipios. Porcentajes con denominadores propios, huecos y cambios territoriales preservados; continentes como subtotales publicados. No asigna la historia municipal a distritos actuales.', '- Nacimiento y progenitores: scripts/build_parents.py publica cuatro grupos SCB UtlSvBakgFinCKM, 2025, a escala municipal. Usa los recuentos y el total de esa misma tabla; no asigna porcentajes municipales a distritos.', '- Resultados XLSX: leer `roster_RD`, preservar ceros iniciales, separar 314 unidades de recogida; reconstruir porcentajes y totales; el ganador se calcula por partido individual.', '- Geometrías: combinar 21 ZIP, asignar EPSG:3006 declarado por Valmyndigheten; reparar tres geometrías inválidas; mantener copia analítica GeoParquet. Para web: arcos compartidos, snap 1 cm, limpieza sin rellenar huecos, simplificación ponderada 15 m, EPSG:4326, precisión de seis decimales, reparación de redondeo registrada. Gzip determinista.', '- SCB PxWeb: seleccionar códigos históricos DeSO 2018 sin sufijo `_DeSO2025`; ambos sexos; estadística 2022 salvo empleo 2021. Datos originales de cuadrícula y geografía no se modifican.', '- Overlay: intersecciones reales y masa de población de cuadrícula. Transferir recuentos, luego calcular porcentajes. Conservar denominadores específicos de educación, empleo, nacimiento y ciudadanía.', '- Educación: categorías postsecundarias 5 y 6 / total de categorías, población 25–64. Empleo: FÖRV / total, población 20–64 según ContentsCode (el título histórico de la tabla dice 16–64; se usa el metadato del contenido).', '- Nacidos fuera = total menos nacidos en Suecia: incluye país desconocido agrupado por SCB. Ciudadanía extranjera = total menos ciudadanía sueca: incluye apátridas y desconocida. Origen extranjero es la categoría SCB `UtlBakgrund=1`, no una de esas sustituciones.', '', '## Registro de originales oficiales','', '| Archivo | URL original | Descargado (UTC) | SHA-256 | Bytes |','|---|---|---|---|---|']
    for d in inventory: lines.append(f"| `{d['file']}` | [Descarga]({d['url']}) | {d['downloaded_at']} | `{d['sha256']}` | {d['bytes']} |")
    lines+=['','## Licencias','', 'Valmyndigheten: reutilización y redistribución con atribución. SCB: CC0. Ver [LICENSE_DATA.md](LICENSE_DATA.md) y [SOURCE_AUDIT.md](SOURCE_AUDIT.md). SVT se usa únicamente en auditoría y diez comprobaciones; su dataset no se redistribuye.','', 'Los metadatos completos de petición, incluyendo listas exactas de códigos y categorías, están en la caché raw. Las URLs están fijadas en `config/sources.json`, `scripts/build_2026.py` `scripts/build_countries.py` , `scripts/build_birth_regions.py` y `scripts/build_district_birth_regions.py` y `scripts/build_parents.py` y `scripts/build_history.py`; una fuente que cambie exige un nuevo archivo de caché, no sobrescribir el anterior.']
    (ROOT/'SOURCES.md').write_text('\n'.join(lines)+'\n')
    write_json(PUBLIC/'provenance.json',inventory)
    for name in ['SOURCES.md','SOURCE_AUDIT.md','LICENSE_DATA.md','MANUAL_CHECKS.md','data_quality_report.md','data_quality_report_2026.md']:
        if (ROOT/name).exists():shutil.copyfile(ROOT/name,PUBLIC/name)
if __name__=='__main__':main()
